fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // The two input vectors must have the same length.
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    // Zip the two vectors together, compare each pair, and collect the results.
    a.iter()
     .zip(b.iter())
     .map(|(x, y)| x <= y)
     .collect()
}

